#include <stdio.h>

int main() {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    long long colSum[1000] = {0};

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int v;
            scanf("%d", &v);
            colSum[j] += v;
        }
    }

    long long min = colSum[0];
    for (int j = 1; j < M; j++) {
        if (colSum[j] < min) {
            min = colSum[j];
        }
    }

    printf("%lld\n", min);
    return 0;
}
